library(shiny)
library(ggplot2)
#(V6)

# --- Génération Stimuli  ---
generer_donnees <- function(n, type, seed_hauteurs) {
  n <- as.numeric(n)
  pool <- seq(10, 90, by = 0.5) 

  if (type == "Uniform") {
    return(seq(15, 85, length.out = n))
  }

  if (type == "Gaussian") {
    poids <- dnorm(pool, mean = 50, sd = 20.21)

  } else if (type == "Bimodal") {
    # Centres à 29.8 et 70.2 (Écart maximal possible)
    # SD interne très faible (1.0) pour isoler les groupes
    poids <- 0.5 * dnorm(pool, 29.8, 1.0) + 0.5 * dnorm(pool, 70.2, 1.0)

  } else if (type == "Trimodal T") {
    # Centres {25.7, 58, 74.3} : Le cluster central est bien détaché
    # SD interne à 1.5 pour garder la variance globale à 408.33
    poids <- 0.33 * dnorm(pool, 25.7, 1.5) + 0.33 * dnorm(pool, 58, 1.5) + 0.34 * dnorm(pool, 74.3, 1.5)

  } else if (type == "Trimodal S") {
    # Centres {25.7, 42, 74.3}
    # SD interne à 1.5
    poids <- 0.33 * dnorm(pool, 25.7, 1.5) + 0.33 * dnorm(pool, 42, 1.5) + 0.34 * dnorm(pool, 74.3, 1.5)
  }

  set.seed(seed_hauteurs) 
  valeurs <- sample(pool, size = n, replace = FALSE, prob = poids / sum(poids))
  return(valeurs)
}

# --- UI ---
ui <- fluidPage(
  tags$head(tags$style(HTML("
    body { background-color: #f4f7f6; font-family: 'Segoe UI', sans-serif; }
    .centered-container { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 95vh; }
    .content-card { background: white; padding: 50px; border-radius: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.05); width: 95%; max-width: 900px; text-align: center; }
    .btn-action { padding: 12px 45px; border-radius: 30px; font-weight: 600; border: none; transition: 0.3s; margin-top: 25px; }
    .btn-start { background-color: #2c3e50; color: white; }
    .btn-next { background-color: #27ae60; color: white; }
    .error-msg { color: #e74c3c; font-weight: bold; margin-top: 15px; }

    /* --- LIKERT SCALE ALIGNMENT --- */
    .likert-container { 
      margin: 40px auto; 
      width: 100%; 
      max-width: 600px; 
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    /* Force the group of buttons to be a horizontal row */
    #conf_score .shiny-options-group {
      display: flex !important;
      flex-direction: row !important;
      justify-content: center !important;
      gap: 50px; 
      width: 100%;
    }

    /* Stack the number (label) ABOVE the radio circle */
    #conf_score .radio-inline {
      display: flex !important;
      flex-direction: column-reverse !important; 
      align-items: center !important;
      margin: 0 !important;
      padding: 0 !important;
      font-size: 1.4em;
      font-weight: bold;
    }

    /* Reset radio button margins so they don't overlap the numbers */
    #conf_score input[type='radio'] {
      margin: 10px 0 0 0 !important; 
      position: static !important; 
      transform: scale(1.5);
    }

    /* The bottom labels (Not confident... Very confident) */
    .label-row-likert {
      display: flex;
      justify-content: space-between;
      width: 100%;
      max-width: 550px;
      color: #7f8c8d;
      font-weight: 500;
      margin-top: 20px;
    }
  "))))

  div(class = "centered-container",
      div(class = "content-card",

          # Setup (PROLIFIC)
          conditionalPanel(condition = "output.phase == 'setup'",
                           h1("Welcome to the experiment"),
                           p("Please maximize your browser window."),
                           p("When you are ready, click 'Start' to begin."),
                           actionButton("start_btn", "Start", class = "btn-action btn-start")
          ),

          # Selection
          conditionalPanel(condition = "output.phase == 'selection'",
                           uiOutput("dynamic_instruction"),
                           plotOutput("dist_plot", 
                                      click = "plot_click", 
                                      brush = brushOpts(id = "plot_brush", resetOnNew = TRUE),
                                      height = "450px"),
                           uiOutput("selection_warning"),
                           actionButton("confirm_btn", "Confirm Selection", class = "btn-action btn-next")
          ),

          # Confidence 
          conditionalPanel(condition = "output.phase == 'certainty'",
                           h2("How confident are you?"),
                           div(class = "likert-container",
                               # numbers-over-buttons
                               radioButtons("conf_score", NULL, 
                                            choices = 1:5, 
                                            selected = character(0), 
                                            inline = TRUE),

                               # text labels at the bottom
                               div(class = "label-row-likert",
                                   span("1 - Not confident"), 
                                   span("3 - Neutral"), 
                                   span("5 - Very confident")
                               )
                           ),
                           uiOutput("conf_warning"),
                           actionButton("next_btn", "Submit & Continue", class = "btn-action btn-start")
          ),

          # End (PROLIFIC)
          conditionalPanel(condition = "output.phase == 'end'", 
                           h1("Finished"), 
                           p("Thank you for your participation!"),
                           br(),
                           tags$a(href = "https://app.prolific.com/submissions/complete?cc=CBB0DPQT", 
                                  "Click here to validate your submission and return to Prolific", 
                                  class = "btn-action btn-next", 
                                  style = "display: inline-block; text-decoration: none;")
          )
      )
  )

  # --- SERVEUR ---
  server <- function(input, output, session) {
    rv <- reactiveValues(
      phase = "setup", 
      trial = 1, 
      start_time = NULL, 
      current_data = NULL, 
      results = data.frame(), 
      trial_list = NULL, 
      show_error = FALSE,
      click_history = c(),
      part_id = NULL,    # Pour stocker l'ID Prolific
      condition = NULL   # Pour stocker la condition (50/50)
    )

    output$phase <- renderText({ rv$phase }); outputOptions(output, "phase", suspendWhenHidden = FALSE)

    output$dynamic_instruction <- renderUI({
      # On utilise rv$condition au lieu de input$condition
      txt <- ifelse(rv$condition == "tall", "Select the tall rectangles.", "Select the tallest rectangles.")
      h2(txt)
    })

    # --- CAPTURE PROLIFIC & ASSIGNATION 50/50 ---
    observe({
      # 1. Capture de l'ID Prolific via l'URL
      query <- parseQueryString(session$clientData$url_search)
      if (!is.null(query[['PROLIFIC_PID']])) {
        rv$part_id <- query[['PROLIFIC_PID']]
      } else {
        # Si testé en local hors Prolific, donne un ID aléatoire
        rv$part_id <- paste0("TEST_", sample(1000:9999, 1)) 
      }

      # 2. Assignation aléatoire (50% tall, 50% tallest)
      if (is.null(rv$condition)) {
        rv$condition <- sample(c("tall", "tallest"), 1)
      }
    })

    observeEvent(input$start_btn, {
      shapes <- c("Uniform", "Gaussian", "Bimodal", "Trimodal T", "Trimodal S")
      orders <- c("shuffled", "ordered")
      sizes  <- c(12, 24, 36, 48)
      design <- expand.grid(shape = shapes, order = orders, size = sizes)
      rv$trial_list <- design[sample(nrow(design)), ] 
      rv$phase <- "selection"
    })

    observe({
      if (rv$phase == "selection" && is.null(rv$current_data)) {
        trial_info <- rv$trial_list[rv$trial, ]
        hauteurs <- generer_donnees(trial_info$size, trial_info$shape, 1000 + rv$trial)

        if (trial_info$order == "ordered") hauteurs <- sort(hauteurs) else hauteurs <- sample(hauteurs)

        rangs <- rank(hauteurs)

        rv$current_data <- data.frame(
          id = 1:length(hauteurs), 
          height = hauteurs, 
          size_rank = rangs, 
          selected = FALSE, 
          display_pos = 1:length(hauteurs)
        )
        rv$click_history <- c() 
        rv$start_time <- Sys.time()
        rv$show_error <- FALSE
      }
    })

    observeEvent(input$plot_click, {
      req(rv$current_data)
      pos <- round(input$plot_click$x)
      val_y <- input$plot_click$y # On récupère la hauteur du clic

      if (pos %in% rv$current_data$display_pos) {
        idx <- which(rv$current_data$display_pos == pos)

        # Le clic doit être inférieur ou égal à la hauteur de la barre
        if (val_y <= rv$current_data$height[idx]) {
          rv$current_data$selected[idx] <- !rv$current_data$selected[idx]

          if (rv$current_data$selected[idx]) {
            rv$click_history <- c(rv$click_history, idx)
          } else {
            rv$click_history <- rv$click_history[rv$click_history != idx]
          }
          rv$show_error <- FALSE
        }
      }
    })
    observeEvent(input$plot_brush, {
      req(rv$current_data)

      selected_indices <- which(
        rv$current_data$display_pos >= input$plot_brush$xmin &
          rv$current_data$display_pos <= input$plot_brush$xmax &
          rv$current_data$height >= input$plot_brush$ymin # La barre doit toucher le bas du rectangle de sélection
      )

      if (length(selected_indices) > 0) {
        for (idx in selected_indices) {
          if (!rv$current_data$selected[idx]) {
            rv$current_data$selected[idx] <- TRUE
            rv$click_history <- c(rv$click_history, idx)
          }
        }
        rv$show_error <- FALSE
      }
    })
    output$selection_warning <- renderUI({
      if (rv$show_error) div(class="error-msg", "Please select at least one rectangle to continue.")
    })

    output$conf_warning <- renderUI({
      if (rv$show_error) div(class="error-msg", "Please select your confidence level.")
    })

    output$dist_plot <- renderPlot({
      req(rv$current_data)
      ggplot(rv$current_data, aes(x = display_pos, y = height, fill = selected)) +
        geom_bar(stat = "identity", width = 0.8, color = NA, show.legend = FALSE) +
        scale_fill_manual(values = c("FALSE" = "#dcdde1", "TRUE" = "#3498db")) +
        theme_void() + coord_cartesian(ylim = c(0, 100))
    })

    observeEvent(input$confirm_btn, {
      if (sum(rv$current_data$selected) > 0) {
        rv$phase <- "certainty"
        rv$show_error <- FALSE
      } else {
        rv$show_error <- TRUE
      }
    })

    observeEvent(input$next_btn, {
      if (is.null(input$conf_score)) {
        rv$show_error <- TRUE
      } else {
        duration <- as.numeric(difftime(Sys.time(), rv$start_time, units = "secs"))
        trial_info <- rv$trial_list[rv$trial, ]
        all_data <- rv$current_data

        pres_ranks   <- paste(all_data$size_rank, collapse = ",")
        pres_heights <- paste(round(all_data$height, 2), collapse = ",")
        sel_ranks    <- paste(all_data$size_rank[rv$click_history], collapse = ",")
        sel_heights  <- paste(round(all_data$height[rv$click_history], 2), collapse = ",")
        sel_pos      <- paste(rv$click_history, collapse = ",")

        res <- data.frame(
          p_id = rv$part_id,                 
          linguistic_form = rv$condition,     
          dist_type = trial_info$shape,
          pres_order = trial_info$order, 
          set_size = trial_info$size, 
          trial_num = rv$trial,
          time_sec = round(duration, 2), 
          confidence = input$conf_score,
          mean_total = mean(all_data$height), 
          sd_total = sd(all_data$height), 
          median_total = median(all_data$height),
          count_sel = length(rv$click_history),
          mean_sel = if(length(rv$click_history)>0) mean(all_data$height[rv$click_history]) else NA,
          min_height_sel = if(length(rv$click_history)>0) min(all_data$height[rv$click_history]) else NA,
          presentation_ranks = pres_ranks,
          presentation_heights = pres_heights,
          selection_ranks = sel_ranks,
          selection_heights = sel_heights,
          selection_positions = sel_pos
        )

        rv$results <- rbind(rv$results, res)

        if (rv$trial < nrow(rv$trial_list)) {
          rv$trial <- rv$trial + 1
          rv$current_data <- NULL
          rv$phase <- "selection"
          updateRadioButtons(session, "conf_score", selected = character(0))
        } else {
          rv$phase <- "end"
          write.csv(rv$results, paste0("Exp_V6_", rv$part_id, ".csv"), row.names = FALSE)
        }
      }
    })
  }

  shinyApp(ui, server)
